import{_ as s,o as t,c as o,a2 as a}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"Sessions and Context","description":"","frontmatter":{},"headers":[],"relativePath":"sessions.md","filePath":"sessions.md"}'),n={name:"sessions.md"};function i(r,e,c,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="sessions-and-context" tabindex="-1">Sessions and Context <a class="header-anchor" href="#sessions-and-context" aria-label="Permalink to &quot;Sessions and Context&quot;">​</a></h1><p>Pi saves a conversation as a session. The active branch of that session supplies conversation history for the next model request. Use session commands to continue work, explore another branch, or reduce the amount of history sent to the model.</p><h2 id="continue-or-switch-sessions" tabindex="-1">Continue or switch sessions <a class="header-anchor" href="#continue-or-switch-sessions" aria-label="Permalink to &quot;Continue or switch sessions&quot;">​</a></h2><p>Pi saves sessions automatically unless you start it with <code>--no-session</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resume</span></span></code></pre></div><p><code>--continue</code> opens the most recent session for the current working directory. <code>--resume</code> opens the session picker. In interactive mode, <code>/resume</code> opens the same picker and <code>/new</code> starts a new session.</p><p>Use <code>/name</code> or <code>--name</code> to assign a recognizable session name. Run <code>/session</code> to verify the current session file, ID, message count, token usage, and cost.</p><p>The session picker lets you search, rename, and delete sessions. It can also show paths, change sorting, and limit results to named sessions. See <a href="./keybindings.html#sessions">Keybindings</a> for its shortcuts.</p><h2 id="choose-how-to-branch" tabindex="-1">Choose how to branch <a class="header-anchor" href="#choose-how-to-branch" aria-label="Permalink to &quot;Choose how to branch&quot;">​</a></h2><p>Pi stores entries as a tree, so returning to an earlier point does not erase the branch you leave.</p><table tabindex="0"><thead><tr><th>Action</th><th>Result</th><th>Use it when</th></tr></thead><tbody><tr><td><code>/tree</code></td><td>Moves within the current session file</td><td>Related alternatives should stay together</td></tr><tr><td><code>/fork</code></td><td>Creates a new session from an earlier user message</td><td>The alternative should become separate work</td></tr><tr><td><code>/clone</code></td><td>Copies the active branch into a new session</td><td>You want a separate copy of the current state</td></tr></tbody></table><p>In <code>/tree</code>, select a user message to put its text back in the editor. Edit and submit it to create another branch. Selecting an assistant response or another entry continues after that entry with an empty editor.</p><p>When you leave a branch, Pi can summarize it and attach that summary to the branch you enter. This preserves relevant work from the abandoned path without including every message from it.</p><p>For the persisted tree and entry types, see <a href="./session-format.html">Session Format</a>.</p><h2 id="manage-conversation-context" tabindex="-1">Manage conversation context <a class="header-anchor" href="#manage-conversation-context" aria-label="Permalink to &quot;Manage conversation context&quot;">​</a></h2><p>The model receives the active branch, not every branch in the session file. Pi combines that history with the system prompt, discovered context files, available tools, and loaded skill descriptions. <a href="./how-pi-works.html#context">How Pi Works</a> describes how those inputs are assembled.</p><p>The footer shows current context usage. When the active context approaches the model&#39;s limit, Pi normally compacts older history automatically. Compaction adds a summary and keeps recent messages. It does not delete the original session entries.</p><p>Run <code>/compact</code> to compact manually. You can add instructions when the summary should preserve a particular topic or decision. Configure automatic compaction and retained history through <a href="./settings.html#compaction">Settings</a>.</p><p>Compaction can fail if the provider is unavailable or cannot accept the summarization request. Correct the provider problem and run <code>/compact</code> again. Disabling automatic compaction does not disable the manual command.</p><p>See <a href="./compaction.html">Compaction Reference</a> for thresholds, retained boundaries, branch-summary behavior, and extension hooks.</p><h2 id="control-session-storage" tabindex="-1">Control session storage <a class="header-anchor" href="#control-session-storage" aria-label="Permalink to &quot;Control session storage&quot;">​</a></h2><p>By default, Pi stores sessions under <code>~/.pi/agent/sessions/</code>, grouped by working directory. Use <code>--session-dir</code>, <code>PI_CODING_AGENT_SESSION_DIR</code>, or the <code>sessionDir</code> setting to choose another location. The CLI option has highest precedence.</p><p>Use <code>--no-session</code> for an ephemeral run. An ephemeral session cannot be resumed after Pi exits.</p><p>Use <code>--session</code> when you already know the session path or ID. Use <code>--fork</code> to create a new session from an existing session before interactive mode starts.</p><h2 id="export-or-share-a-session" tabindex="-1">Export or share a session <a class="header-anchor" href="#export-or-share-a-session" aria-label="Permalink to &quot;Export or share a session&quot;">​</a></h2><p>Use <code>/export</code> to write the current session as HTML or JSONL. Use <code>/share</code> to upload it and get a viewer link. By default, Pi uses a Radius artifact when Radius authentication is configured; otherwise, it uses a private GitHub gist. Set <a href="./settings.html#sessions-and-context"><code>sessionShareDestination</code></a> to <code>gist</code> or <code>radius</code> to force one destination.</p><p>Review exported or shared sessions first. They can contain prompts, model responses, tool arguments, command output, file contents, and extension messages.</p><h2 id="report-a-bug" tabindex="-1">Report a bug <a class="header-anchor" href="#report-a-bug" aria-label="Permalink to &quot;Report a bug&quot;">​</a></h2><p>Run <code>/bug [description]</code> to prepare a private report for the Pi developers. You can include the session transcript, omit it, or ask the current model to summarize the problem. Review any transcript or generated summary because it can contain sensitive conversation data.</p><p>The report includes environment and provider configuration without credential values, plus recorded error diagnostics. Upload it through <code>radius.pi.dev</code> or export the same report as a zip to inspect and share yourself. Uploads do not require a login; Radius authentication attributes the report to your account so the developers can follow up. If an upload fails, Pi offers to export the zip.</p>`,30)])])}const m=s(n,[["render",i]]);export{u as __pageData,m as default};
